const input = $json.body || $json;
const rawText = String(
  input.brief || input.text || input.message || input.content || input.note || ''
).trim();
const lower = rawText.toLowerCase();
const lines = rawText.split(String.fromCharCode(10)).map((line) => line.trim()).filter(Boolean);

const kv = {};
for (const line of lines) {
  const separator = line.includes(':') ? ':' : (line.includes('=') ? '=' : null);
  if (!separator) continue;
  const parts = line.split(separator);
  const key = (parts.shift() || '').trim().toLowerCase();
  const value = parts.join(separator).trim();
  if (key && value) kv[key] = value;
}

function slug(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function detectVertical(text) {
  if (text.includes('solar + ev') || text.includes('solar+ev') || text.includes('hybrid')) return 'hybrid';
  if (text.includes('wallbox') || text.includes('carregador') || text.includes('eletromobil') || text.includes('mobilidade eletr') || text.includes('veiculo eletr') || text.includes('recarga')) return 'ev';
  return 'solar';
}

function detectAudience(text, vertical) {
  if (text.includes('cfo') || text.includes('facility') || text.includes('gestor') || text.includes('diretor') || text.includes('empresa') || text.includes('frota') || text.includes('condominio') || text.includes('condomínio')) return 'b2b';
  if (text.includes('casa') || text.includes('residencial') || text.includes('familia') || text.includes('proprietario') || text.includes('morador')) return 'b2c';
  return vertical === 'ev' ? 'b2b' : 'b2c';
}

function detectCity(text) {
  const cities = ['florianopolis', 'sao jose', 'palhoca', 'joinville', 'blumenau', 'itajai', 'balneario camboriu', 'chapeco', 'criciuma', 'jaragua do sul'];
  const found = cities.find((city) => text.includes(city));
  if (!found) return 'Florianopolis';
  return found.split(' ').map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' ');
}

function detectGoal(text) {
  if (text.includes('parceria')) return 'partner_acquisition';
  if (text.includes('awareness') || text.includes('alcance') || text.includes('autoridade')) return 'awareness';
  if (text.includes('demo') || text.includes('diagnostico') || text.includes('orcamento') || text.includes('orçamento') || text.includes('lead')) return 'lead_gen';
  return 'lead_gen';
}

function detectOffer(vertical, audience, goal) {
  if (vertical === 'hybrid') return 'calculadora solar + ev';
  if (vertical === 'ev' && audience === 'b2b') return 'auditoria de recarga para condominio/frota';
  if (vertical === 'ev') return 'calculadora de wallbox residencial';
  if (audience === 'b2b') return 'diagnostico de ranking e confianca local';
  return goal === 'awareness' ? 'conteudo de prova social local' : 'calculadora de economia solar';
}

function detectChannels(inputValue) {
  const raw = inputValue || kv.channels || kv.canais || 'linkedin,instagram,x,whatsapp';
  if (Array.isArray(raw)) {
    return raw.map((item) => String(item).trim().toLowerCase()).filter(Boolean);
  }
  return String(raw).split(',').map((item) => item.trim().toLowerCase()).filter(Boolean);
}

const vertical = String(input.vertical || kv.vertical || detectVertical(lower)).toLowerCase();
const audience = String(input.audience || kv.audience || detectAudience(lower, vertical)).toLowerCase();
const city = input.city || kv.city || detectCity(lower);
const goal = String(input.goal || kv.goal || detectGoal(lower)).toLowerCase();
const channels = detectChannels(input.channels || input.canais);
const publishMode = String(input.publish || input.mode || input.publish_mode || kv.publish || kv.mode || '').toLowerCase();
const publish_mode = ['auto', 'publish', 'live', 'published'].includes(publishMode) || lower.includes('#publish') ? 'auto' : 'draft';
const offer = input.offer || kv.offer || detectOffer(vertical, audience, goal);
const categorySlug = vertical === 'hybrid' ? 'integracao-solar-ev' : (vertical === 'ev' ? (audience === 'b2b' ? 'carregadores-comerciais' : 'carregadores-residenciais') : (audience === 'b2b' ? 'energia-solar-comercial-industrial' : 'energia-solar-residencial'));
const baseUrl = 'https://www.avaliasolar.com.br';
const campaignSlug = slug([vertical, city, goal].join('-'));
const landingUrl = `${baseUrl}/categories/${categorySlug}?utm_source=internal&utm_medium=growth_command&utm_campaign=${campaignSlug}&utm_content=${goal}`;
const publishLinkedIn = publish_mode === 'auto' && (channels.includes('linkedin') || channels.includes('all'));
const publishX = publish_mode === 'auto' && (channels.includes('x') || channels.includes('twitter') || channels.includes('all'));

return [{
  json: {
    campaign_id: `GHC-${Date.now()}`,
    raw_text: rawText,
    trigger_source: String(input.source || 'webhook').toLowerCase(),
    vertical,
    audience,
    city,
    goal,
    offer,
    category_slug: categorySlug,
    landing_url: landingUrl,
    channels,
    publish_mode,
    publish_linkedin: publishLinkedIn,
    publish_x: publishX,
    created_at: new Date().toISOString()
  }
}];

const data = $json;
const nl = String.fromCharCode(10);

const hookByVertical = {
  solar: data.audience === 'b2b'
    ? `Empresa solar sem ranking vira commodity em ${data.city}.`
    : `Conta de luz alta em ${data.city} nao precisa continuar igual mes que vem.`,
  ev: data.audience === 'b2b'
    ? `Recarga para condominio ou frota nao pode ser decidida no escuro.`
    : `O wallbox certo muda o custo por km mais do que parece.`,
  hybrid: `Solar + EV e a dupla que corta energia e combustivel ao mesmo tempo.`
};

const hook = hookByVertical[data.vertical] || hookByVertical.solar;
const proofLine = data.audience === 'b2b'
  ? 'ranking verificavel, trust score e prova social local'
  : 'economia real, reviews reais e comparacao simples';

const ctaByGoal = {
  lead_gen: `Quer que eu te envie o briefing e o link com UTM?`,
  awareness: `Compartilhe com o time e salve para usar depois.`,
  partner_acquisition: `Se voce quer parceria, responda com parceria.`
};

const cta = ctaByGoal[data.goal] || ctaByGoal.lead_gen;
const hashtagByVertical = {
  solar: '#EnergiaSolar #SolarBrasil #AvaliaSolar',
  ev: '#MobilidadeEletrica #Wallbox #AvaliaSolar',
  hybrid: '#EnergiaSolar #MobilidadeEletrica #AvaliaSolar'
};

const hashtags = hashtagByVertical[data.vertical] || hashtagByVertical.solar;
const xPostBase = `${hook} ${data.city}. ${data.offer}. ${data.landing_url}`;
const xPost = xPostBase.length > 280 ? `${xPostBase.slice(0, 277)}...` : xPostBase;

const linkedinPost = [
  hook,
  '',
  '3 sinais que sempre convertem melhor nesse mercado:',
  `- confianca verificavel`,
  `- prova local em ${data.city}`,
  `- resposta rapida no WhatsApp`,
  '',
  `Oferta: ${data.offer}`,
  `CTA: ${cta}`,
  '',
  data.landing_url,
  hashtags
].join(nl);

const instagramCaption = [
  hook,
  '',
  `Por que isso importa em ${data.city}:`,
  `- ${proofLine}`,
  `- oferta: ${data.offer}`,
  `- CTA: ${cta}`,
  '',
  data.landing_url,
  hashtags
].join(nl);

const whatsappCopy = [
  hook,
  `Oferta: ${data.offer}`,
  `${data.landing_url}`,
  `${cta}`
].join(nl);

const slackSummary = [
  '*Growth pack pronto*',
  `- Campaign: ${data.campaign_id}`,
  `- Vertical: ${data.vertical}`,
  `- Audience: ${data.audience}`,
  `- City: ${data.city}`,
  `- Goal: ${data.goal}`,
  `- Publish mode: ${data.publish_mode}`,
  `- LinkedIn: ${data.publish_linkedin ? 'yes' : 'no'}`,
  `- X: ${data.publish_x ? 'yes' : 'no'}`,
  `- Landing: ${data.landing_url}`,
  '',
  'Drafts generated for LinkedIn, Instagram, X and WhatsApp copy.',
  'Slack is the internal control tower; public publish is optional.'
].join(nl);

return [{
  json: {
    ...data,
    hook,
    proof_line: proofLine,
    hashtags,
    linkedin_post: linkedinPost,
    x_post: xPost,
    instagram_caption: instagramCaption,
    whatsapp_copy: whatsappCopy,
    slack_summary: slackSummary,
    publish_linkedin: data.publish_linkedin,
    publish_x: data.publish_x
  }
}];
